:root {
  color-scheme: light dark;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, "PingFang SC", sans-serif;
  font-synthesis: none;

  /* Pudding 风格中性双模调色板 */
  --ml-bg: light-dark(#f8fafc, #090e17);
  --ml-panel: light-dark(#ffffff, #111827);
  --ml-panel-subtle: light-dark(#f1f5f9, #1a2234);
  --ml-border: light-dark(#e2e8f0, #1f293d);
  --ml-border-hover: light-dark(#cbd5e1, #334155);
  --ml-text: light-dark(#0f172a, #f8fafc);
  --ml-text-muted: light-dark(#64748b, #94a3b8);
  --ml-text-dim: light-dark(#94a3b8, #64748b);

  /* 主题与功能品牌色 */
  --ml-primary: light-dark(#0284c7, #38bdf8);
  --ml-primary-hover: light-dark(#0369a1, #0ea5e9);
  --ml-primary-bg: light-dark(#f0f9ff, rgba(56, 189, 248, 0.12));
  --ml-primary-border: light-dark(#bae6fd, rgba(56, 189, 248, 0.3));

